package com.radix.app

/** Localized copy for the practice bank; Boolean symbols, equations and bit patterns are preserved. */
internal object PracticeTextTranslations {
    private data class Text3(val fr:String,val es:String,val pt:String)
    private val entries=mapOf(
        "Every input matters" to Text3("Chaque entrée compte","Cada entrada importa","Cada entrada conta"),
        "AND: A=1, B=0. What is Y?" to Text3("AND : A=1, B=0. Quelle est la valeur de Y ?","AND: A=1, B=0. ¿Cuánto vale Y?","AND: A=1, B=0. Qual é o valor de Y?"),
        "AND needs all inputs high." to Text3("AND exige que toutes les entrées soient à 1.","AND necesita que todas las entradas estén en 1.","AND exige todas as entradas em nível alto."),
        "One input is 0, so A·B is 0." to Text3("Une entrée vaut 0, donc A·B vaut 0.","Una entrada es 0, así que A·B es 0.","Uma entrada vale 0, então A·B é 0."),
        "At least one" to Text3("Au moins une","Al menos una","Pelo menos uma"),
        "OR: A=0, B=0. What is Y?" to Text3("OR : A=0, B=0. Quelle est la valeur de Y ?","OR: A=0, B=0. ¿Cuánto vale Y?","OR: A=0, B=0. Qual é o valor de Y?"),
        "OR needs at least one 1." to Text3("OR exige au moins une entrée à 1.","OR necesita al menos un 1.","OR exige pelo menos uma entrada em 1."),
        "Neither input is 1, so Y=0." to Text3("Aucune entrée ne vaut 1, donc Y=0.","Ninguna entrada es 1, así que Y=0.","Nenhuma entrada vale 1, então Y=0."),
        "Flip the value" to Text3("Inversez la valeur","Invierte el valor","Inverta o valor"),
        "NOT: A=1. What is Y?" to Text3("NOT : A=1. Quelle est la valeur de Y ?","NOT: A=1. ¿Cuánto vale Y?","NOT: A=1. Qual é o valor de Y?"),
        "An output bubble means inversion." to Text3("La petite bulle en sortie indique une inversion.","La burbuja de salida indica una inversión.","A pequena bolha na saída indica inversão."),
        "NOT reverses 1 to 0." to Text3("NOT transforme 1 en 0.","NOT convierte 1 en 0.","NOT transforma 1 em 0."),
        "AND, then invert" to Text3("AND, puis inversion","AND y luego invertir","AND e depois inverter"),
        "NAND: A=1, B=1. What is Y?" to Text3("NAND : A=1, B=1. Quelle est la valeur de Y ?","NAND: A=1, B=1. ¿Cuánto vale Y?","NAND: A=1, B=1. Qual é o valor de Y?"),
        "First evaluate AND." to Text3("Calculez d’abord AND.","Primero calcula AND.","Primeiro calcule AND."),
        "AND produces 1; NAND inverts it to 0." to Text3("AND produit 1 ; NAND l’inverse en 0.","AND produce 1; NAND lo invierte a 0.","AND produz 1; NAND o inverte para 0."),
        "OR, then invert" to Text3("OR, puis inversion","OR y luego invertir","OR e depois inverter"),
        "NOR: A=0, B=0. What is Y?" to Text3("NOR : A=0, B=0. Quelle est la valeur de Y ?","NOR: A=0, B=0. ¿Cuánto vale Y?","NOR: A=0, B=0. Qual é o valor de Y?"),
        "OR produces 0; NOR inverts it to 1." to Text3("OR produit 0 ; NOR l’inverse en 1.","OR produce 0; NOR lo invierte a 1.","OR produz 0; NOR o inverte para 1."),
        "Odd means one" to Text3("Impair signifie 1","Impar significa 1","Ímpar significa 1"),
        "Three-input XOR: A=B=C=1. What is Y?" to Text3("XOR à trois entrées : A=B=C=1. Quelle est la valeur de Y ?","XOR de tres entradas: A=B=C=1. ¿Cuánto vale Y?","XOR de três entradas: A=B=C=1. Qual é o valor de Y?"),
        "Count the number of 1s, not whether exactly one is high." to Text3("Comptez les 1, ne vérifiez pas s’il n’y en a qu’un seul.","Cuenta los 1; no compruebes si hay exactamente uno.","Conte os 1; não verifique se há apenas um."),
        "Three 1s is odd parity, so Y=1. Multi-input XOR is not an exactly-one detector." to Text3("Trois 1 donnent une parité impaire, donc Y=1. Un XOR à plusieurs entrées ne détecte pas exactement un seul 1.","Tres 1 dan paridad impar, así que Y=1. Un XOR de varias entradas no detecta exactamente un único 1.","Três 1 resultam em paridade ímpar, então Y=1. Um XOR com várias entradas não detecta exatamente um único 1."),
        "Even means one" to Text3("Pair signifie 1","Par significa 1","Par significa 1"),
        "Four-input XNOR: all four inputs are 1. What is Y?" to Text3("XNOR à quatre entrées : les quatre entrées valent 1. Quelle est la valeur de Y ?","XNOR de cuatro entradas: las cuatro entradas valen 1. ¿Cuánto vale Y?","XNOR de quatro entradas: todas valem 1. Qual é o valor de Y?"),
        "XNOR is the complement of XOR." to Text3("XNOR est le complément de XOR.","XNOR es el complemento de XOR.","XNOR é o complemento de XOR."),
        "Four 1s is even parity, so XNOR produces 1." to Text3("Quatre 1 donnent une parité paire, donc XNOR produit 1.","Cuatro 1 dan paridad par, así que XNOR produce 1.","Quatro 1 resultam em paridade par, então XNOR produz 1."),
        "Pass it through" to Text3("Laissez passer","Déjalo pasar","Deixe passar"),
        "BUFFER: A=0. What is Y?" to Text3("BUFFER : A=0. Quelle est la valeur de Y ?","BUFFER: A=0. ¿Cuánto vale Y?","BUFFER: A=0. Qual é o valor de Y?"),
        "A buffer does not invert." to Text3("Un BUFFER n’inverse pas le signal.","Un BUFFER no invierte la señal.","Um BUFFER não inverte o sinal."),
        "The output follows its one input: Y=0." to Text3("La sortie suit son unique entrée : Y=0.","La salida sigue su única entrada: Y=0.","A saída acompanha sua única entrada: Y=0."),
        "Two ones make two" to Text3("Deux uns font deux","Dos unos hacen dos","Dois uns formam dois"),
        "Half adder: A=1, B=1. Give Sum, Carry." to Text3("Demi-additionneur : A=1, B=1. Donnez Somme et Retenue.","Semisumador: A=1, B=1. Indica Suma y Acarreo.","Meio somador: A=1, B=1. Informe Soma e Carry."),
        "Write decimal 2 as a two-bit result." to Text3("Écrivez 2 en décimal sur deux bits.","Escribe el 2 decimal como resultado de dos bits.","Escreva o 2 decimal como resultado de dois bits."),
        "1+1=2=10₂. Sum is the low bit 0; Carry is the high bit 1." to Text3("1+1=2=10₂. La somme est le bit faible 0 ; la retenue est le bit fort 1.","1+1=2=10₂. La suma es el bit bajo 0; el acarreo es el bit alto 1.","1+1=2=10₂. A soma é o bit menos significativo 0; o carry é o bit mais significativo 1."),
        "Remember carry-in" to Text3("N’oubliez pas la retenue d’entrée","Recuerda el acarreo de entrada","Lembre do carry de entrada"),
        "Full adder: A=B=Cin=1. Give Sum, Cout." to Text3("Additionneur complet : A=B=Cin=1. Donnez Somme et Cout.","Sumador completo: A=B=Cin=1. Indica Suma y Cout.","Somador completo: A=B=Cin=1. Informe Soma e Cout."),
        "The total is 3, not 2." to Text3("Le total vaut 3, pas 2.","El total es 3, no 2.","O total é 3, não 2."),
        "1+1+1=3=11₂: Sum=1 and Cout=1." to Text3("1+1+1=3=11₂ : Somme=1 et Cout=1.","1+1+1=3=11₂: Suma=1 y Cout=1.","1+1+1=3=11₂: Soma=1 e Cout=1."),
        "Borrow one" to Text3("Empruntez un","Pide prestado uno","Pegue emprestado um"),
        "Half subtractor: A=0, B=1. Give Difference, Borrow." to Text3("Demi-soustracteur : A=0, B=1. Donnez Différence et Emprunt.","Semirrestador: A=0, B=1. Indica Diferencia y Préstamo.","Meio subtrator: A=0, B=1. Informe Diferença e Empréstimo."),
        "0−1 needs a borrow from the next position." to Text3("0−1 nécessite un emprunt à la position suivante.","0−1 necesita un préstamo de la posición siguiente.","0−1 exige um empréstimo da posição seguinte."),
        "After borrowing 2, 2−1=1; Difference=1 and Borrow=1." to Text3("Après l’emprunt de 2, 2−1=1 ; Différence=1 et Emprunt=1.","Tras pedir prestado 2, 2−1=1; Diferencia=1 y Préstamo=1.","Após emprestar 2, 2−1=1; Diferença=1 e Empréstimo=1."),
        "Borrow-in counts too" to Text3("L’emprunt d’entrée compte aussi","El préstamo de entrada también cuenta","O empréstimo de entrada também conta"),
        "Full subtractor: A=0, B=1, Bin=1. Give Difference, Bout." to Text3("Soustracteur complet : A=0, B=1, Bin=1. Donnez Différence et Bout.","Restador completo: A=0, B=1, Bin=1. Indica Diferencia y Bout.","Subtrator completo: A=0, B=1, Bin=1. Informe Diferença e Bout."),
        "Compute A−B−Bin." to Text3("Calculez A−B−Bin.","Calcula A−B−Bin.","Calcule A−B−Bin."),
        "0−1−1=−2. At one bit, Difference=0 and Borrow=1." to Text3("0−1−1=−2. Sur un bit, Différence=0 et Emprunt=1.","0−1−1=−2. Con un bit, Diferencia=0 y Préstamo=1.","0−1−1=−2. Com um bit, Diferença=0 e Empréstimo=1."),
        "Read the selector" to Text3("Lisez le sélecteur","Lee el selector","Leia o seletor"),
        "4:1 MUX: D0=0, D1=0, D2=1, D3=0; S1S0=10. Y?" to Text3("MUX 4:1 : D0=0, D1=0, D2=1, D3=0 ; S1S0=10. Y ?","MUX 4:1: D0=0, D1=0, D2=1, D3=0; S1S0=10. ¿Y?","MUX 4:1: D0=0, D1=0, D2=1, D3=0; S1S0=10. Y?"),
        "10₂ selects input number 2." to Text3("10₂ sélectionne l’entrée numéro 2.","10₂ selecciona la entrada número 2.","10₂ seleciona a entrada número 2."),
        "The MUX routes D2, which is 1. It does not OR all data inputs." to Text3("Le MUX transmet D2, qui vaut 1. Il ne réalise pas un OR de toutes les entrées de données.","El MUX dirige D2, que vale 1. No aplica OR a todas las entradas de datos.","O MUX encaminha D2, que vale 1. Ele não faz OR de todas as entradas de dados."),
        "The highest input wins" to Text3("L’entrée la plus prioritaire l’emporte","Gana la entrada de mayor prioridad","A entrada de maior prioridade vence"),
        "Priority encoder: D3=D2=D1=D0=1. Give Y1Y0 and Valid." to Text3("Codeur prioritaire : D3=D2=D1=D0=1. Donnez Y1Y0 et Valid.","Codificador de prioridad: D3=D2=D1=D0=1. Indica Y1Y0 y Valid.","Codificador de prioridade: D3=D2=D1=D0=1. Informe Y1Y0 e Valid."),
        "Priority is D3 > D2 > D1 > D0." to Text3("La priorité est D3 > D2 > D1 > D0.","La prioridad es D3 > D2 > D1 > D0.","A prioridade é D3 > D2 > D1 > D0."),
        "D3 wins, so its index is 11₂; at least one input is high, so Valid=1." to Text3("D3 l’emporte, son indice est donc 11₂ ; au moins une entrée est à 1, donc Valid=1.","Gana D3, así que su índice es 11₂; al menos una entrada está en 1, por lo que Valid=1.","D3 vence, então seu índice é 11₂; pelo menos uma entrada está em nível alto, portanto Valid=1."),
        "Keep the fifth bit" to Text3("Gardez le cinquième bit","Conserva el quinto bit","Mantenha o quinto bit"),
        "4-bit adder: 1111 + 0001, Cin=0. Give S3S2S1S0 and Cout." to Text3("Additionneur 4 bits : 1111 + 0001, Cin=0. Donnez S3S2S1S0 et Cout.","Sumador de 4 bits: 1111 + 0001, Cin=0. Indica S3S2S1S0 y Cout.","Somador de 4 bits: 1111 + 0001, Cin=0. Informe S3S2S1S0 e Cout."),
        "15+1=16 needs five bits." to Text3("15+1=16 nécessite cinq bits.","15+1=16 necesita cinco bits.","15+1=16 precisa de cinco bits."),
        "The result is 10000₂. The low four sum bits are 0000 and Cout=1." to Text3("Le résultat est 10000₂. Les quatre bits faibles de la somme valent 0000 et Cout=1.","El resultado es 10000₂. Los cuatro bits bajos de la suma son 0000 y Cout=1.","O resultado é 10000₂. Os quatro bits menos significativos da soma são 0000 e Cout=1."),
        "Start at the MSB" to Text3("Commencez par le MSB","Empieza por el MSB","Comece pelo MSB"),
        "2-bit comparator: A=10, B=01. Which relation is true?" to Text3("Comparateur 2 bits : A=10, B=01. Quelle relation est vraie ?","Comparador de 2 bits: A=10, B=01. ¿Qué relación es verdadera?","Comparador de 2 bits: A=10, B=01. Qual relação é verdadeira?"),
        "10₂ is decimal 2, not decimal ten." to Text3("10₂ vaut 2 en décimal, pas dix.","10₂ es 2 en decimal, no diez.","10₂ vale 2 em decimal, não dez."),
        "A=2 and B=1, so only A>B is high." to Text3("A=2 et B=1, donc seule la sortie A>B vaut 1.","A=2 y B=1, así que solo A>B está en 1.","A=2 e B=1, então apenas A>B está em nível alto."),
        "High is not an edge" to Text3("Un niveau haut n’est pas un front","Un nivel alto no es un flanco","Nível alto não é borda"),
        "D flip-flop: Q=1, CLK stays high, D changes to 0. Q next?" to Text3("Bascule D : Q=1, CLK reste à 1 et D passe à 0. Quelle est la prochaine valeur de Q ?","Flip-flop D: Q=1, CLK sigue alto y D cambia a 0. ¿Cuál es el próximo valor de Q?","Flip-flop D: Q=1, CLK continua alto e D muda para 0. Qual é o próximo Q?"),
        "Capture needs a 0→1 transition." to Text3("L’échantillonnage nécessite un front 0→1.","La captura necesita una transición 0→1.","A captura exige uma transição de 0→1."),
        "No new rising edge occurs. Q holds 1 even though D is now 0." to Text3("Aucun nouveau front montant ne se produit. Q reste à 1, même si D vaut maintenant 0.","No hay un nuevo flanco ascendente. Q conserva 1 aunque D ahora sea 0.","Não ocorre outra borda de subida. Q mantém 1, embora D agora seja 0."),
        "A latch follows a level" to Text3("Un verrou suit le niveau","Un latch sigue el nivel","Um latch acompanha o nível"),
        "D latch: Q=0, EN=1, D becomes 1. Q next?" to Text3("Verrou D : Q=0, EN=1, D passe à 1. Quelle est la prochaine valeur de Q ?","Latch D: Q=0, EN=1, D pasa a 1. ¿Cuál es el próximo valor de Q?","Latch D: Q=0, EN=1, D passa para 1. Qual é o próximo Q?"),
        "An enabled D latch is transparent." to Text3("Un verrou D activé est transparent.","Un latch D habilitado es transparente.","Um latch D habilitado é transparente."),
        "EN=1 lets Q follow D immediately. No clock edge is required." to Text3("EN=1 permet à Q de suivre immédiatement D. Aucun front d’horloge n’est nécessaire.","EN=1 permite que Q siga D de inmediato. No se necesita un flanco de reloj.","EN=1 permite que Q acompanhe D imediatamente. Não é necessária uma borda de clock."),
        "Toggle, do not set" to Text3("Basculez, ne forcez pas","Alterna, no establez","Alterne, não force"),
        "JK flip-flop: Q=1, J=K=1 at a rising edge. Q next?" to Text3("Bascule JK : Q=1, J=K=1 sur un front montant. Quelle est la prochaine valeur de Q ?","Flip-flop JK: Q=1, J=K=1 en un flanco ascendente. ¿Cuál es el próximo valor de Q?","Flip-flop JK: Q=1, J=K=1 na borda de subida. Qual é o próximo Q?"),
        "Both high means toggle." to Text3("Les deux entrées à 1 provoquent une bascule.","Ambas entradas en 1 hacen que cambie de estado.","As duas entradas em nível alto fazem alternar."),
        "JK=11 toggles Q from 1 to 0. It is valid in this ideal edge model." to Text3("JK=11 fait passer Q de 1 à 0. Cet état est valide dans ce modèle idéal à front.","JK=11 cambia Q de 1 a 0. Es válido en este modelo ideal por flanco.","JK=11 alterna Q de 1 para 0. Isso é válido neste modelo ideal acionado por borda."),
        "No second capture" to Text3("Pas de seconde capture","No hay una segunda captura","Não ocorre uma segunda captura"),
        "T flip-flop: Q=1, T=1, CLK stays high. Q next?" to Text3("Bascule T : Q=1, T=1, CLK reste à 1. Quelle est la prochaine valeur de Q ?","Flip-flop T: Q=1, T=1, CLK sigue alto. ¿Cuál es el próximo valor de Q?","Flip-flop T: Q=1, T=1, CLK continua alto. Qual é o próximo Q?"),
        "A high level is not another rising edge." to Text3("Un niveau haut ne constitue pas un nouveau front montant.","Un nivel alto no es otro flanco ascendente.","Um nível alto não é outra borda de subida."),
        "Q remains 1. T toggles only at each new rising edge." to Text3("Q reste à 1. T ne bascule qu’à chaque nouveau front montant.","Q permanece en 1. T solo alterna en cada nuevo flanco ascendente.","Q permanece em 1. T só alterna em cada nova borda de subida."),
        "Forbidden does not mean complementary" to Text3("Interdit ne signifie pas complémentaire","Prohibido no significa complementario","Proibido não significa complementar"),
        "NOR SR latch: S=R=1. What happens?" to Text3("Verrou SR à NOR : S=R=1. Que se passe-t-il ?","Latch SR con NOR: S=R=1. ¿Qué ocurre?","Latch SR com NOR: S=R=1. O que acontece?"),
        "NOR outputs are forced low by a high reset/set input." to Text3("Une entrée SET/RESET à 1 force les sorties NOR à 0.","Una entrada SET/RESET en 1 fuerza las salidas NOR a 0.","Uma entrada SET/RESET em nível alto força as saídas NOR para 0."),
        "Both physical outputs are 0; stored memory is indeterminate. Simultaneous release to hold keeps X until valid recovery." to Text3("Les deux sorties physiques valent 0 ; l’état mémorisé est indéterminé. Un relâchement simultané vers l’état de maintien conserve X jusqu’à une récupération valide.","Ambas salidas físicas son 0; la memoria almacenada es indeterminada. Soltar ambas a la vez para mantener conserva X hasta una recuperación válida.","As duas saídas físicas são 0; a memória armazenada é indeterminada. Soltar ambas simultaneamente para manter conserva X até uma recuperação válida."),
        "Active-low changes the rule" to Text3("L’actif-bas change la règle","El nivel activo bajo cambia la regla","Nível ativo baixo muda a regra"),
        "NAND SR latch: nS=nR=0. What happens?" to Text3("Verrou SR à NAND : nS=nR=0. Que se passe-t-il ?","Latch SR con NAND: nS=nR=0. ¿Qué ocurre?","Latch SR com NAND: nS=nR=0. O que acontece?"),
        "A 0 on either NAND input forces its output to 1." to Text3("Un 0 sur une entrée NAND force sa sortie à 1.","Un 0 en cualquier entrada NAND fuerza su salida a 1.","Um 0 em qualquer entrada NAND força sua saída para 1."),
        "Both physical outputs are 1 and stored memory is indeterminate. The active-low hold combination is 11." to Text3("Les deux sorties physiques valent 1 et l’état mémorisé est indéterminé. La combinaison de maintien actif-bas est 11.","Ambas salidas físicas son 1 y la memoria almacenada es indeterminada. La combinación de mantenimiento activo bajo es 11.","As duas saídas físicas são 1 e a memória armazenada é indeterminada. A combinação de retenção ativa em nível baixo é 11."),
        "Wrap at the width" to Text3("Rebouclez à la largeur choisie","Vuelve al inicio del ancho","Recomece no limite da largura"),
        "3-bit counter: Q=111, EN=1, RESET=0. After one rising edge?" to Text3("Compteur 3 bits : Q=111, EN=1, RESET=0. Après un front montant ?","Contador de 3 bits: Q=111, EN=1, RESET=0. ¿Tras un flanco ascendente?","Contador de 3 bits: Q=111, EN=1, RESET=0. Após uma borda de subida?"),
        "There are eight states, 0 through 7." to Text3("Il y a huit états, de 0 à 7.","Hay ocho estados, del 0 al 7.","Há oito estados, de 0 a 7."),
        "The next count is (7+1) mod 8 = 0, so Q=000." to Text3("Le compte suivant est (7+1) mod 8 = 0, donc Q=000.","La cuenta siguiente es (7+1) mod 8 = 0, por tanto Q=000.","A próxima contagem é (7+1) mod 8 = 0, então Q=000."),
        "Insert at Q0" to Text3("Insérez sur Q0","Inserta en Q0","Insira em Q0"),
        "Shift register: Q3Q2Q1Q0=0110, D=1, EN=1, RESET=0. Next edge?" to Text3("Registre à décalage : Q3Q2Q1Q0=0110, D=1, EN=1, RESET=0. Au prochain front ?","Registro de desplazamiento: Q3Q2Q1Q0=0110, D=1, EN=1, RESET=0. ¿En el próximo flanco?","Registrador de deslocamento: Q3Q2Q1Q0=0110, D=1, EN=1, RESET=0. Próxima borda?"),
        "Move each bit toward Q3; D enters Q0." to Text3("Décalez chaque bit vers Q3 ; D entre en Q0.","Desplaza cada bit hacia Q3; D entra en Q0.","Desloque cada bit em direção a Q3; D entra em Q0."),
        "Q3←Q2, Q2←Q1, Q1←Q0, Q0←D produces 1101." to Text3("Q3←Q2, Q2←Q1, Q1←Q0, Q0←D donne 1101.","Q3←Q2, Q2←Q1, Q1←Q0, Q0←D produce 1101.","Q3←Q2, Q2←Q1, Q1←Q0, Q0←D resulta em 1101."),
        "Clocked forbidden state" to Text3("État interdit échantillonné","Estado prohibido capturado","Estado proibido capturado pelo clock"),
        "SR flip-flop: Q=1, S=R=1 at a rising edge. Q next?" to Text3("Bascule SR : Q=1, S=R=1 sur un front montant. Quelle est la prochaine valeur de Q ?","Flip-flop SR: Q=1, S=R=1 en un flanco ascendente. ¿Cuál es el próximo valor de Q?","Flip-flop SR: Q=1, S=R=1 na borda de subida. Qual é o próximo Q?"),
        "The forbidden combination is captured on the edge." to Text3("La combinaison interdite est échantillonnée sur le front.","La combinación prohibida se captura en el flanco.","A combinação proibida é capturada na borda."),
        "This ideal SR flip-flop stores unknown X after capturing 11. A valid set/reset edge recovers a known state." to Text3("Cette bascule SR idéale mémorise X, inconnu, après avoir capturé 11. Un front SET/RESET valide rétablit un état connu.","Este flip-flop SR ideal guarda X, desconocido, tras capturar 11. Un flanco SET/RESET válido recupera un estado conocido.","Este flip-flop SR ideal armazena X, desconhecido, após capturar 11. Uma borda SET/RESET válida recupera um estado conhecido."),
        "Circulate the one" to Text3("Faites circuler le 1","Haz circular el uno","Faça o um circular"),
        "Ring counter: Q=1000, EN=1, RESET=0. Next rising edge?" to Text3("Compteur en anneau : Q=1000, EN=1, RESET=0. Prochain front montant ?","Contador en anillo: Q=1000, EN=1, RESET=0. ¿Próximo flanco ascendente?","Contador em anel: Q=1000, EN=1, RESET=0. Próxima borda de subida?"),
        "The old Q3 bit wraps around to Q0." to Text3("L’ancien bit Q3 revient en Q0.","El antiguo bit Q3 vuelve a Q0.","O bit Q3 anterior retorna em Q0."),
        "Rotate 1000 left: the high bit re-enters at Q0, giving 0001." to Text3("Décalez 1000 vers la gauche : le bit fort revient en Q0, ce qui donne 0001.","Rota 1000 a la izquierda: el bit alto vuelve a Q0 y queda 0001.","Rotacione 1000 para a esquerda: o bit mais alto retorna em Q0, resultando em 0001."),
        "Invert the feedback" to Text3("Inversez la rétroaction","Invierte la realimentación","Inverta a realimentação"),
        "Johnson counter: Q=1111, EN=1, RESET=0. Next rising edge?" to Text3("Compteur Johnson : Q=1111, EN=1, RESET=0. Prochain front montant ?","Contador Johnson: Q=1111, EN=1, RESET=0. ¿Próximo flanco ascendente?","Contador Johnson: Q=1111, EN=1, RESET=0. Próxima borda de subida?"),
        "The complemented old Q3 enters Q0." to Text3("Le complément de l’ancien Q3 entre en Q0.","El complemento del antiguo Q3 entra en Q0.","O complemento do Q3 anterior entra em Q0."),
        "Shift left and insert NOT old Q3 = 0: the next state is 1110." to Text3("Décalez vers la gauche et insérez NOT de l’ancien Q3 = 0 : l’état suivant est 1110.","Desplaza a la izquierda e inserta NOT del antiguo Q3 = 0: el estado siguiente es 1110.","Desloque à esquerda e insira NOT do Q3 anterior = 0: o próximo estado é 1110."),
        "Reset wins over enable" to Text3("RESET est prioritaire sur EN","RESET tiene prioridad sobre EN","RESET tem prioridade sobre EN"),
        "3-bit counter: Q=101, EN=0, RESET=1. After a rising edge?" to Text3("Compteur 3 bits : Q=101, EN=0, RESET=1. Après un front montant ?","Contador de 3 bits: Q=101, EN=0, RESET=1. ¿Tras un flanco ascendente?","Contador de 3 bits: Q=101, EN=0, RESET=1. Após uma borda de subida?"),
        "RESET is synchronous and takes priority over EN." to Text3("RESET est synchrone et prioritaire sur EN.","RESET es síncrono y tiene prioridad sobre EN.","RESET é síncrono e tem prioridade sobre EN."),
        "At the edge, RESET=1 clears Q to 000 even though EN=0. Before the edge it would still hold 101." to Text3("Sur le front, RESET=1 remet Q à 000 même si EN=0. Avant le front, Q resterait à 101.","En el flanco, RESET=1 pone Q en 000 aunque EN=0. Antes del flanco seguiría en 101.","Na borda, RESET=1 limpa Q para 000 mesmo com EN=0. Antes da borda, Q ainda manteria 101."),
        "Not signed magnitude" to Text3("Ce n’est pas le signe-magnitude","No es signo y magnitud","Não é sinal e magnitude"),
        "Encode −13 in 8-bit two’s complement." to Text3("Codez −13 en complément à deux sur 8 bits.","Codifica −13 en complemento a dos de 8 bits.","Codifique −13 em complemento de dois de 8 bits."),
        "Encode +13, invert every bit, then add 1." to Text3("Codez +13, inversez chaque bit, puis ajoutez 1.","Codifica +13, invierte cada bit y luego suma 1.","Codifique +13, inverta cada bit e depois some 1."),
        "+13=00001101; invert→11110010; add 1→11110011. Signed magnitude 10001101 is a different representation." to Text3("+13=00001101 ; inversion→11110010 ; +1→11110011. 10001101 en signe-magnitude est une autre représentation.","+13=00001101; invertir→11110010; sumar 1→11110011. 10001101 en signo y magnitud es otra representación.","+13=00001101; inverter→11110010; somar 1→11110011. 10001101 em sinal e magnitude é outra representação."),
        "The upper endpoint" to Text3("La borne supérieure","El límite superior","O limite superior"),
        "Largest unsigned 8-bit integer?" to Text3("Quel est le plus grand entier non signé sur 8 bits ?","¿Cuál es el mayor entero sin signo de 8 bits?","Qual é o maior inteiro sem sinal de 8 bits?"),
        "There are 2^8 possible words, starting at zero." to Text3("Il existe 2^8 mots possibles, à partir de zéro.","Hay 2^8 palabras posibles, empezando por cero.","Há 2^8 palavras possíveis, começando em zero."),
        "The range is 0 through 2^8−1 = 255. Signed two’s complement instead ends at 127." to Text3("L’intervalle va de 0 à 2^8−1 = 255. En complément à deux signé, la borne supérieure est 127.","El rango va de 0 a 2^8−1 = 255. En complemento a dos con signo, el máximo es 127.","A faixa vai de 0 a 2^8−1 = 255. Em complemento de dois com sinal, o máximo é 127."),
        "Neighboring codes" to Text3("Codes voisins","Códigos vecinos","Códigos vizinhos"),
        "Gray code for the 4-bit binary word 0100?" to Text3("Quel est le code Gray du mot binaire 0100 sur 4 bits ?","¿Cuál es el código Gray de la palabra binaria 0100 de 4 bits?","Qual é o código Gray da palavra binária 0100 de 4 bits?"),
        "XOR binary with itself shifted right one bit." to Text3("Effectuez le XOR du binaire avec lui-même décalé d’un bit vers la droite.","Haz XOR del binario con sí mismo desplazado un bit a la derecha.","Faça XOR do binário com ele mesmo deslocado um bit à direita."),
        "0100 XOR 0010 = 0110. Gray code is not positional binary." to Text3("0100 XOR 0010 = 0110. Le code Gray n’est pas un binaire positionnel.","0100 XOR 0010 = 0110. El código Gray no es binario posicional.","0100 XOR 0010 = 0110. Código Gray não é binário posicional."),
        "One nibble per digit" to Text3("Un quartet par chiffre","Un nibble por dígito","Um nibble por dígito"),
        "BCD encoding of decimal 12?" to Text3("Quel est le codage BCD de 12 en décimal ?","¿Cuál es la codificación BCD del decimal 12?","Qual é a codificação BCD do decimal 12?"),
        "Encode the decimal digits 1 and 2 separately." to Text3("Codez séparément les chiffres décimaux 1 et 2.","Codifica por separado los dígitos decimales 1 y 2.","Codifique os dígitos decimais 1 e 2 separadamente."),
        "BCD is 0001 0010. Ordinary binary for decimal 12 is 1100; these are different encodings." to Text3("Le BCD vaut 0001 0010. Le binaire ordinaire de 12 vaut 1100 : ce sont deux codages différents.","BCD es 0001 0010. El binario normal de 12 es 1100; son codificaciones distintas.","BCD é 0001 0010. O binário comum de 12 é 1100; são codificações diferentes."),
        "Invert the whole product" to Text3("Inversez tout le produit","Invierte todo el producto","Inverta todo o produto"),
        "Which expression equals NOT (A AND B)?" to Text3("Quelle expression équivaut à NOT (A AND B) ?","¿Qué expresión equivale a NOT (A AND B)?","Qual expressão equivale a NOT (A AND B)?"),
        "De Morgan changes AND to OR when distributing NOT." to Text3("La loi de De Morgan remplace AND par OR lorsqu’on distribue NOT.","De Morgan cambia AND por OR al distribuir NOT.","De Morgan troca AND por OR ao distribuir NOT."),
        "NOT (A·B)=A′+B′. Inverting only the variables but keeping AND is incorrect." to Text3("NOT (A·B)=A′+B′. Inverser seulement les variables en gardant AND est incorrect.","NOT (A·B)=A′+B′. Invertir solo las variables y mantener AND es incorrecto.","NOT (A·B)=A′+B′. Inverter apenas as variáveis e manter AND está incorreto."),
        "Multiplication first" to Text3("La multiplication d’abord","Primero la multiplicación","Multiplicação primeiro"),
        "In A + BC, which operation happens first?" to Text3("Dans A + BC, quelle opération est effectuée en premier ?","En A + BC, ¿qué operación se realiza primero?","Em A + BC, qual operação acontece primeiro?"),
        "Adjacency is AND and binds more tightly than OR." to Text3("La juxtaposition signifie AND, prioritaire sur OR.","La yuxtaposición significa AND y tiene prioridad sobre OR.","A justaposição significa AND e tem precedência sobre OR."),
        "A + BC means A OR (B AND C), not (A OR B) AND C." to Text3("A + BC signifie A OR (B AND C), et non (A OR B) AND C.","A + BC significa A OR (B AND C), no (A OR B) AND C.","A + BC significa A OR (B AND C), não (A OR B) AND C."),
        "Different inputs" to Text3("Entrées différentes","Entradas distintas","Entradas diferentes"),
        "Which equals A XOR B?" to Text3("Quelle expression équivaut à A XOR B ?","¿Cuál equivale a A XOR B?","Qual equivale a A XOR B?"),
        "XOR is true when the two inputs differ." to Text3("XOR vaut 1 lorsque les deux entrées diffèrent.","XOR es verdadero cuando las dos entradas son distintas.","XOR é verdadeiro quando as duas entradas são diferentes."),
        "A′B + AB′ covers 01 and 10 only. AB + A′B′ is XNOR instead." to Text3("A′B + AB′ couvre uniquement 01 et 10. AB + A′B′ correspond plutôt à XNOR.","A′B + AB′ cubre solo 01 y 10. AB + A′B′ corresponde a XNOR.","A′B + AB′ cobre apenas 01 e 10. AB + A′B′ corresponde a XNOR."),
        "One dominates OR" to Text3("Un 1 domine OR","El uno domina OR","Um domina OR"),
        "Simplify 1 OR (A AND B)." to Text3("Simplifiez 1 OR (A AND B).","Simplifica 1 OR (A AND B).","Simplifique 1 OR (A AND B)."),
        "OR with 1 is always high." to Text3("OR avec 1 vaut toujours 1.","OR con 1 siempre vale 1.","OR com 1 sempre resulta em nível alto."),
        "Every truth-table row is 1. Both SOP and POS reduce to constant 1." to Text3("Chaque ligne de la table vaut 1. SOP et POS se réduisent toutes deux à la constante 1.","Todas las filas de la tabla valen 1. SOP y POS se reducen a la constante 1.","Todas as linhas da tabela são 1. SOP e POS se reduzem à constante 1.")
    )

    fun translate(source:String,language:String):String?=entries[source]?.let { text -> when(language.lowercase()) {
        "fr"->text.fr
        "es"->text.es
        "pt"->text.pt
        else->null
    } }
}
